mapper.select:
SELECT * FROM expenses
WHERE id = #{id}
  AND is_deleted = 0

SELECT e.*, TRIM(CONCAT(COALESCE(up.first_name, ''), ' ', COALESCE(up.last_name, ''))) AS submitter_name, TRIM(CONCAT(COALESCE(rp.first_name, ''), ' ', COALESCE(rp.last_name, ''))) AS reviewer_name, CASE WHEN e.status = 'PENDING_REVIEW' THEN dup.duplicate_of_id ELSE NULL END AS duplicate_of_id, CASE WHEN e.status = 'PENDING_REVIEW' THEN dup_e.status ELSE NULL END AS duplicate_of_status FROM expenses e LEFT JOIN user_profiles up ON up.user_sub = e.user_sub LEFT JOIN user_profiles rp ON rp.user_sub = e.reviewed_by LEFT JOIN ( SELECT e1.id AS expense_id, MIN(e2.id) AS duplicate_of_id FROM expenses e1 JOIN expenses e2 ON e2.user_sub = e1.user_sub AND e2.type = 'RECEIPT' AND LOWER(TRIM(e2.vendor_name)) = LOWER(TRIM(e1.vendor_name)) AND e2.amount = e1.amount AND e2.receipt_date = e1.receipt_date AND e2.status IN ('PENDING_REVIEW', 'APPROVED', 'PAID') AND e2.id < e1.id WHERE e1.type = 'RECEIPT' GROUP BY e1.id ) dup ON dup.expense_id = e.id LEFT JOIN expenses dup_e ON dup_e.id = dup.duplicate_of_id WHERE e.status IN
#{s}
AND e.is_deleted = 0 ORDER BY (e.status = 'PENDING_REVIEW') DESC, CASE WHEN e.status = 'PENDING_REVIEW' THEN e.submitted_at END ASC, CASE WHEN e.status != 'PENDING_REVIEW' THEN e.reviewed_at END DESC

