UPDATE expenses SET status = 'PAID', paid_at = NOW(), retention_expires_at = DATE_ADD(CURDATE(), INTERVAL 10 YEAR) WHERE id IN
#{id}
AND status = 'APPROVED'

mapper.select:
SELECT * FROM expenses
WHERE status IN ('APPROVED', 'REJECTED')
  AND YEAR(created_at)  = #{year}
  AND MONTH(created_at) = #{month}
  AND is_deleted = 0
ORDER BY amount DESC
